      continue;
    }
    if (udp.beginPacket(useLaptopIp ? laptop : WiFi.broadcastIP(), UDP_PORT)) {
      udp.write(packet, sizeof(packet));
      if (udp.endPacket()) {
        packetsSent = packetsSent + 1;
      }
    }
  }
}

